#!/usr/bin/env python3
"""Apply Port G-buffer motion to core025 direct+indirect Rasterizer draws."""
import sys,json
from pathlib import Path
root=Path(sys.argv[1]).resolve()
edits=json.loads(r'''{"src/video_core/renderer_vulkan/vk_rasterizer.h":[["#include \"video_core/renderer_vulkan/vk_pipeline_cache.h\"","#include \"video_core/renderer_vulkan/vk_pipeline_cache.h\"\n#include \"video_core/renderer_vulkan/vk_object_motion.h\"",1],["    PipelineCache pipeline_cache;","    PipelineCache pipeline_cache;\n    ObjectMotion object_motion;\n    u64 object_motion_generation{~u64{0}};",1]],"src/video_core/renderer_vulkan/vk_rasterizer.cpp":[["#include <array>","#include <array>\n#include <dlfcn.h>\n#include <span>\n#include <xxhash.h>",1],["      pipeline_cache{instance, scheduler, liverpool} {","      pipeline_cache{instance, scheduler, liverpool}, object_motion{instance,scheduler} {",1],["    PrepareRenderState(pipeline);","    if(object_motion.Enabled()) {\n        using Generation=u64(*)();\n        static auto get_gen=reinterpret_cast<Generation>(\n            dlsym(RTLD_DEFAULT,\"bs4_port_frame_generation\"));\n        if(get_gen) {\n            const u64 current=get_gen();\n            if(object_motion_generation!=current) {\n                object_motion.OnFrameStart();\n                object_motion_generation=current;\n            }\n        }\n    }\n    PrepareRenderState(pipeline);",2],["    const auto state = BeginRendering(pipeline);\n\n    buffer_cache.BindVertexBuffers(*pipeline);","    auto state = BeginRendering(pipeline);\n    if(pipeline->GetGraphicsKey().motion_vectors && object_motion.Enabled())\n        object_motion.Attach(state,state.width,state.height);\n\n    buffer_cache.BindVertexBuffers(*pipeline);",2],["    pipeline->BindResources(set_writes, buffer_barriers, push_data);\n    UpdateDynamicState(pipeline, is_indexed);\n    scheduler.BeginRendering(state);\n\n    const auto& vs_info = pipeline->GetStage(Shader::LogicalStage::Vertex);\n    const auto& fetch_shader = pipeline->GetFetchShader();\n    const auto [vertex_offset, instance_offset] = GetDrawOffsets(regs, vs_info, fetch_shader);","    const auto& vs_info = pipeline->GetStage(Shader::LogicalStage::Vertex);\n    const auto& fetch_shader = pipeline->GetFetchShader();\n    const auto [vertex_offset, instance_offset] = GetDrawOffsets(regs, vs_info, fetch_shader);\n    if(pipeline->GetGraphicsKey().motion_vectors && object_motion.Enabled()) {\n        // Port draw matching: shaders, resource addresses, indexed topology,\n        // base vertex/instance and the changing bone palette.\n        u64 geometry=vs_info.pgm_hash;\n        u64 palette=0;\n        bool gate=true;\n        for(const auto& res:vs_info.buffers){\n            if(res.IsSpecial())continue;\n            const auto buf=res.GetSharp(vs_info);\n            if(!buf.Valid())continue;\n            geometry^=buf.base_address+0x9e3779b97f4a7c15ull+\n                    (geometry<<6)+(geometry>>2);\n            geometry^=buf.GetSize()+0x9e3779b97f4a7c15ull+\n                    (geometry<<6)+(geometry>>2);\n            if(buf.GetStride()!=16)continue;\n            const auto role=Motion::ClassifyBuffer(buf.GetSize());\n            if(role==Motion::BufferRole::Skeleton)gate=false;\n            if(role==Motion::BufferRole::SmallSkeleton &&\n               memory->IsValidGpuMapping(buf.base_address,0) &&\n               memory->ClampRangeSize(buf.base_address,buf.GetSize())==buf.GetSize()) {\n                palette=XXH3_64bits_withSeed(\n                    reinterpret_cast<const void*>(buf.base_address),\n                    buf.GetSize(),palette);\n            }\n        }\n        const u32 instances=regs.num_instances.NumInstances();\n        const u32 index_size=regs.index_buffer_type.index_type==\n            AmdGpu::IndexType::Index16?2u:4u;\n        const VAddr indices=is_indexed\n            ? regs.index_base_address.Address<VAddr>()+u64(index_offset)*index_size:0;\n        push_data.motion_param=0;\n        if(!gate || object_motion.Moving({\n            .shader=vs_info.pgm_hash,.geometry=geometry,.indices=indices,\n            .index_count=regs.num_indices,.instances=instances,\n            .first_instance=instance_offset},palette)) {\n            Motion::VertexRange range{vertex_offset,regs.num_indices};\n            u64 topology=0;\n            if(is_indexed) {\n                range={};\n                const u64 bytes=u64(regs.num_indices)*index_size;\n                if(indices && memory->IsValidGpuMapping(indices,0) &&\n                   memory->ClampRangeSize(indices,bytes)==bytes){\n                    const auto scan=object_motion.IndexRange(\n                        {indices,regs.num_indices,index_size,\n                         s32(vertex_offset),regs.enable_primitive_restart!=0},[&]{\n                        const auto* data=reinterpret_cast<const void*>(indices);\n                        const auto vertex_range=index_size==2\n                            ? Motion::IndexedRange(\n                                std::span(reinterpret_cast<const u16*>(data),\n                                          size_t(regs.num_indices)),\n                                s32(vertex_offset),regs.enable_primitive_restart!=0)\n                            : Motion::IndexedRange(\n                                std::span(reinterpret_cast<const u32*>(data),\n                                          size_t(regs.num_indices)),\n                                s32(vertex_offset),regs.enable_primitive_restart!=0);\n                        return Motion::IndexRangeCache::Result{\n                            vertex_range,XXH3_64bits(data,bytes)};\n                    });\n                    range=scan.range;\n                    topology=scan.topology;\n                }\n            }\n            push_data.motion_param=object_motion.PrepareDraw({\n                .shader=vs_info.pgm_hash,.geometry=geometry,.indices=indices,\n                .topology=topology,.index_count=regs.num_indices,\n                .instances=instances,.first_instance=instance_offset,\n                .vertices=range});\n        }\n    }\n    pipeline->BindResources(set_writes, buffer_barriers, push_data);\n    UpdateDynamicState(pipeline, is_indexed);\n    scheduler.BeginRendering(state);",1]]}''')
for path,changes in edits.items():
    f=root/path
    s=f.read_text()
    for before,after,count in changes:
        if s.count(before)!=count:
            raise RuntimeError(f"{path}: source anchor changed: {before[:95]!r}")
        s=s.replace(before,after)
    f.write_text(s)
print("PASS: Port object-motion history, keyed draws and RT7 connected to core025 native rasterizer")
